10: import prettyFormat from 'pretty-format';
11: import {CompilerOutputMode, Logger, ProgramContext} from '.';
12: import {
13:   HIRFunction,
14:   ReactiveFunction,
15:   assertConsistentIdentifiers,
16:   assertTerminalPredsExist,
17:   assertTerminalSuccessorsExist,
18:   assertValidBlockNesting,
19:   assertValidMutableRanges,
20:   buildReactiveScopeTerminalsHIR,
21:   lower,
22:   mergeConsecutiveBlocks,
23:   mergeOverlappingReactiveScopesHIR,
24:   pruneUnusedLabelsHIR,
25: } from '../HIR';
26: import {
27:   Environment,
28:   EnvironmentConfig,
29:   ReactFunctionType,
30: } from '../HIR/Environment';
31: import {findContextIdentifiers} from '../HIR/FindContextIdentifiers';
32: import {
33:   analyseFunctions,
34:   dropManualMemoization,
35:   inferReactivePlaces,
36:   inlineImmediatelyInvokedFunctionExpressions,
