43: import {
44:   CodegenFunction,
45:   alignObjectMethodScopes,
46:   assertScopeInstructionsWithinScopes,
47:   assertWellFormedBreakTargets,
48:   buildReactiveFunction,
49:   codegenFunction,
50:   extractScopeDeclarationsFromDestructuring,
51:   inferReactiveScopeVariables,
52:   memoizeFbtAndMacroOperandsInSameScope,
53:   mergeReactiveScopesThatInvalidateTogether,
54:   promoteUsedTemporaries,
55:   propagateEarlyReturns,
56:   pruneHoistedContexts,
57:   pruneNonEscapingScopes,
58:   pruneNonReactiveDependencies,
