206:   optimizePropsMethodCalls(hir);
207:   log({kind: 'hir', name: 'OptimizePropsMethodCalls', value: hir});
208: 
209:   analyseFunctions(hir);
210:   log({kind: 'hir', name: 'AnalyseFunctions', value: hir});
211: 
212:   const mutabilityAliasingErrors = inferMutationAliasingEffects(hir);
213:   log({kind: 'hir', name: 'InferMutationAliasingEffects', value: hir});
214:   if (env.enableValidations) {
215:     if (mutabilityAliasingErrors.isErr()) {
216:       throw mutabilityAliasingErrors.unwrapErr();
217:     }
218:   }
219: 
220:   if (env.outputMode === 'ssr') {
221:     optimizeForSSR(hir);
222:     log({kind: 'hir', name: 'OptimizeForSSR', value: hir});
223:   }
224: 
225:   // Note: Has to come after infer reference effects because "dead" code may still affect inference
226:   deadCodeElimination(hir);
227:   log({kind: 'hir', name: 'DeadCodeElimination', value: hir});
228:   pruneMaybeThrows(hir);
229:   log({kind: 'hir', name: 'PruneMaybeThrows', value: hir});
230: 
231:   const mutabilityAliasingRangeErrors = inferMutationAliasingRanges(hir, {
232:     isFunctionExpression: false,
233:   });
234:   log({kind: 'hir', name: 'InferMutationAliasingRanges', value: hir});
235:   if (env.enableValidations) {
236:     if (mutabilityAliasingRangeErrors.isErr()) {
237:       throw mutabilityAliasingRangeErrors.unwrapErr();
238:     }
239:     validateLocalsNotReassignedAfterRender(hir);
240:   }
241: 
242:   if (env.enableValidations) {
243:     if (env.config.assertValidMutableRanges) {
244:       assertValidMutableRanges(hir);
245:     }
246: 
247:     if (env.config.validateRefAccessDuringRender) {
248:       validateNoRefAccessInRender(hir).unwrap();
249:     }
250: 
251:     if (env.config.validateNoSetStateInRender) {
252:       validateNoSetStateInRender(hir).unwrap();
253:     }
254: 
255:     if (
256:       env.config.validateNoDerivedComputationsInEffects_exp &&
257:       env.outputMode === 'lint'
258:     ) {
259:       env.logErrors(validateNoDerivedComputationsInEffects_exp(hir));
260:     } else if (env.config.validateNoDerivedComputationsInEffects) {
261:       validateNoDerivedComputationsInEffects(hir);
262:     }
263: 
264:     if (env.config.validateNoSetStateInEffects && env.outputMode === 'lint') {
265:       env.logErrors(validateNoSetStateInEffects(hir, env));
266:     }
267: 
268:     if (env.config.validateNoJSXInTryStatements && env.outputMode === 'lint') {
269:       env.logErrors(validateNoJSXInTryStatement(hir));
270:     }
271: 
272:     if (env.config.validateNoImpureFunctionsInRender) {
273:       validateNoImpureFunctionsInRender(hir).unwrap();
274:     }
275: 
276:     validateNoFreezingKnownMutableFunctions(hir).unwrap();
277:   }
278: 
279:   inferReactivePlaces(hir);
280:   log({kind: 'hir', name: 'InferReactivePlaces', value: hir});
281: 
282:   if (env.enableValidations) {
283:     if (
284:       env.config.validateExhaustiveMemoizationDependencies ||
285:       env.config.validateExhaustiveEffectDependencies
286:     ) {
287:       // NOTE: this relies on reactivity inference running first
288:       validateExhaustiveDependencies(hir).unwrap();
289:     }
290:   }
291: 
292:   rewriteInstructionKindsBasedOnReassignment(hir);
293:   log({
294:     kind: 'hir',
295:     name: 'RewriteInstructionKindsBasedOnReassignment',
296:     value: hir,
297:   });
298: 
299:   if (
300:     env.enableValidations &&
301:     env.config.validateStaticComponents &&
302:     env.outputMode === 'lint'
303:   ) {
304:     env.logErrors(validateStaticComponents(hir));
305:   }
306: 
307:   if (env.enableMemoization) {
308:     /**
309:      * Only create reactive scopes (which directly map to generated memo blocks)
310:      * if inferred memoization is enabled. This makes all later passes which
311:      * transform reactive-scope labeled instructions no-ops.
312:      */
313:     inferReactiveScopeVariables(hir);
314:     log({kind: 'hir', name: 'InferReactiveScopeVariables', value: hir});
315:   }
316: 
317:   const fbtOperands = memoizeFbtAndMacroOperandsInSameScope(hir);
318:   log({
319:     kind: 'hir',
320:     name: 'MemoizeFbtAndMacroOperandsInSameScope',
321:     value: hir,
322:   });
323: 
324:   if (env.config.enableJsxOutlining) {
325:     outlineJSX(hir);
326:   }
327: 
328:   if (env.config.enableNameAnonymousFunctions) {
329:     nameAnonymousFunctions(hir);
330:     log({
331:       kind: 'hir',
332:       name: 'NameAnonymousFunctions',
333:       value: hir,
334:     });
335:   }
336: 
337:   if (env.config.enableFunctionOutlining) {
338:     outlineFunctions(hir, fbtOperands);
339:     log({kind: 'hir', name: 'OutlineFunctions', value: hir});
340:   }
341: 
342:   alignMethodCallScopes(hir);
343:   log({
344:     kind: 'hir',
345:     name: 'AlignMethodCallScopes',
346:     value: hir,
347:   });
348: 
349:   alignObjectMethodScopes(hir);
350:   log({
351:     kind: 'hir',
352:     name: 'AlignObjectMethodScopes',
353:     value: hir,
354:   });
355: 
356:   pruneUnusedLabelsHIR(hir);
357:   log({
358:     kind: 'hir',
359:     name: 'PruneUnusedLabelsHIR',
360:     value: hir,
361:   });
362: 
363:   alignReactiveScopesToBlockScopesHIR(hir);
364:   log({
365:     kind: 'hir',
366:     name: 'AlignReactiveScopesToBlockScopesHIR',
367:     value: hir,
368:   });
369: 
370:   mergeOverlappingReactiveScopesHIR(hir);
371:   log({
372:     kind: 'hir',
373:     name: 'MergeOverlappingReactiveScopesHIR',
374:     value: hir,
375:   });
376:   assertValidBlockNesting(hir);
377: 
378:   buildReactiveScopeTerminalsHIR(hir);
379:   log({
380:     kind: 'hir',
381:     name: 'BuildReactiveScopeTerminalsHIR',
382:     value: hir,
383:   });
384: 
385:   assertValidBlockNesting(hir);
386: 
387:   flattenReactiveLoopsHIR(hir);
388:   log({
389:     kind: 'hir',
390:     name: 'FlattenReactiveLoopsHIR',
391:     value: hir,
392:   });
393: 
394:   flattenScopesWithHooksOrUseHIR(hir);
395:   log({
396:     kind: 'hir',
397:     name: 'FlattenScopesWithHooksOrUseHIR',
398:     value: hir,
399:   });
400:   assertTerminalSuccessorsExist(hir);
401:   assertTerminalPredsExist(hir);
402:   propagateScopeDependenciesHIR(hir);
403:   log({
404:     kind: 'hir',
405:     name: 'PropagateScopeDependenciesHIR',
406:     value: hir,
407:   });
408: 
409:   const reactiveFunction = buildReactiveFunction(hir);
410:   log({
411:     kind: 'reactive',
412:     name: 'BuildReactiveFunction',
413:     value: reactiveFunction,
414:   });
415: 
416:   assertWellFormedBreakTargets(reactiveFunction);
417: 
418:   pruneUnusedLabels(reactiveFunction);
419:   log({
420:     kind: 'reactive',
421:     name: 'PruneUnusedLabels',
422:     value: reactiveFunction,
423:   });
424:   assertScopeInstructionsWithinScopes(reactiveFunction);
425: 
426:   pruneNonEscapingScopes(reactiveFunction);
427:   log({
428:     kind: 'reactive',
429:     name: 'PruneNonEscapingScopes',
430:     value: reactiveFunction,
431:   });
432: 
433:   pruneNonReactiveDependencies(reactiveFunction);
434:   log({
435:     kind: 'reactive',
436:     name: 'PruneNonReactiveDependencies',
437:     value: reactiveFunction,
438:   });
439: 
440:   pruneUnusedScopes(reactiveFunction);
441:   log({
442:     kind: 'reactive',
443:     name: 'PruneUnusedScopes',
444:     value: reactiveFunction,
445:   });
446: 
447:   mergeReactiveScopesThatInvalidateTogether(reactiveFunction);
448:   log({
449:     kind: 'reactive',
450:     name: 'MergeReactiveScopesThatInvalidateTogether',
451:     value: reactiveFunction,
452:   });
453: 
454:   pruneAlwaysInvalidatingScopes(reactiveFunction);
455:   log({
456:     kind: 'reactive',
457:     name: 'PruneAlwaysInvalidatingScopes',
458:     value: reactiveFunction,
459:   });
460: 
461:   propagateEarlyReturns(reactiveFunction);
462:   log({
463:     kind: 'reactive',
464:     name: 'PropagateEarlyReturns',
465:     value: reactiveFunction,
466:   });
467: 
468:   pruneUnusedLValues(reactiveFunction);
469:   log({
470:     kind: 'reactive',
471:     name: 'PruneUnusedLValues',
472:     value: reactiveFunction,
473:   });
474: 
475:   promoteUsedTemporaries(reactiveFunction);
476:   log({
477:     kind: 'reactive',
478:     name: 'PromoteUsedTemporaries',
479:     value: reactiveFunction,
480:   });
481: 
482:   extractScopeDeclarationsFromDestructuring(reactiveFunction);
483:   log({
484:     kind: 'reactive',
485:     name: 'ExtractScopeDeclarationsFromDestructuring',
486:     value: reactiveFunction,
487:   });
488: 
489:   stabilizeBlockIds(reactiveFunction);
490:   log({
491:     kind: 'reactive',
492:     name: 'StabilizeBlockIds',
493:     value: reactiveFunction,
494:   });
495: 
496:   const uniqueIdentifiers = renameVariables(reactiveFunction);
497:   log({
498:     kind: 'reactive',
499:     name: 'RenameVariables',
500:     value: reactiveFunction,
501:   });
502: 
503:   pruneHoistedContexts(reactiveFunction);
504:   log({
505:     kind: 'reactive',
506:     name: 'PruneHoistedContexts',
507:     value: reactiveFunction,
508:   });
509: 
510:   if (
511:     env.config.enablePreserveExistingMemoizationGuarantees ||
512:     env.config.validatePreserveExistingMemoizationGuarantees
513:   ) {
514:     validatePreservedManualMemoization(reactiveFunction).unwrap();
515:   }
516: 
517:   const ast = codegenFunction(reactiveFunction, {
518:     uniqueIdentifiers,
519:     fbtOperands,
520:   }).unwrap();
521:   log({kind: 'ast', name: 'Codegen', value: ast});
522:   for (const outlined of ast.outlined) {
523:     log({kind: 'ast', name: 'Codegen (outlined)', value: outlined.fn});
524:   }
525: 
526:   if (env.config.validateSourceLocations) {
527:     validateSourceLocations(func, ast).unwrap();
528:   }
529: 
530:   /**
531:    * This flag should be only set for unit / fixture tests to check
532:    * that Forget correctly handles unexpected errors (e.g. exceptions
533:    * thrown by babel functions or other unexpected exceptions).
534:    */
535:   if (env.config.throwUnknownException__testonly) {
536:     throw new Error('unexpected error');
537:   }
538: 
539:   return ast;
540: }
541: 
542: export function compileFn(
543:   func: NodePath<
544:     t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
545:   >,
546:   config: EnvironmentConfig,
547:   fnType: ReactFunctionType,
548:   mode: CompilerOutputMode,
549:   programContext: ProgramContext,
550:   logger: Logger | null,
551:   filename: string | null,
552:   code: string | null,
553: ): CodegenFunction {
554:   return run(
555:     func,
556:     config,
557:     fnType,
558:     mode,
559:     programContext,
560:     logger,
561:     filename,
562:     code,
563:   );
564: }
