7: 
8: import * as t from '@babel/types';
9: import {z} from 'zod/v4';
10: import {
11:   CompilerDiagnostic,
12:   CompilerError,
13:   CompilerErrorDetail,
14:   CompilerErrorDetailOptions,
15: } from '../CompilerError';
16: import {
17:   EnvironmentConfig,
18:   ExternalFunction,
19:   parseEnvironmentConfig,
20:   tryParseExternalFunction,
21: } from '../HIR/Environment';
22: import {hasOwnProperty} from '../Utils/utils';
23: import {fromZodError} from 'zod-validation-error/v4';
24: import {CompilerPipelineValue} from './Pipeline';
25: 
26: const PanicThresholdOptionsSchema = z.enum([
27:   /*
28:    * Any errors will panic the compiler by throwing an exception, which will
29:    * bubble up to the nearest exception handler above the Forget transform.
30:    * If Forget is invoked through `BabelPluginReactCompiler`, this will at the least
31:    * skip Forget compilation for the rest of current file.
32:    */
33:   'all_errors',
34:   /*
35:    * Panic by throwing an exception only on critical or unrecognized errors.
36:    * For all other errors, skip the erroring function without inserting
37:    * a Forget-compiled version (i.e. same behavior as noEmit).
38:    */
39:   'critical_errors',
40:   // Never panic by throwing an exception.
41:   'none',
42: ]);
43: 
44: export type PanicThresholdOptions = z.infer<typeof PanicThresholdOptionsSchema>;
45: const DynamicGatingOptionsSchema = z.object({
46:   source: z.string(),
47: });
48: export type DynamicGatingOptions = z.infer<typeof DynamicGatingOptionsSchema>;
49: const CustomOptOutDirectiveSchema = z
50:   .nullable(z.array(z.string()))
51:   .default(null);
52: type CustomOptOutDirective = z.infer<typeof CustomOptOutDirectiveSchema>;
53: 
54: export type PluginOptions = Partial<{
55:   environment: Partial<EnvironmentConfig>;
56: 
57:   logger: Logger | null;
58: 
59:   /*
60:    * Specifying a `gating` config, makes Forget compile and emit a separate
61:    * version of the function gated by importing the `gating.importSpecifierName` from the
62:    * specified `gating.source`.
63:    *
64:    * For example:
65:    *   gating: {
66:    *     source: 'ReactForgetFeatureFlag',
67:    *     importSpecifierName: 'isForgetEnabled_Pokes',
68:    *   }
69:    *
70:    * produces:
71:    *   import {isForgetEnabled_Pokes} from 'ReactForgetFeatureFlag';
72:    *
73:    *   Foo_forget()   {}
74:    *
75:    *   Foo_uncompiled() {}
76:    *
77:    *   var Foo = isForgetEnabled_Pokes() ? Foo_forget : Foo_uncompiled;
78:    */
79:   gating: ExternalFunction | null;
80: 
81:   /**
82:    * If specified, this enables dynamic gating which matches `use memo if(...)`
83:    * directives.
84:    *
85:    * Example usage:
86:    * ```js
87:    * // @dynamicGating:{"source":"myModule"}
88:    * export function MyComponent() {
89:    *   'use memo if(isEnabled)';
90:    *    return <div>...</div>;
91:    * }
92:    * ```
93:    * This will emit:
94:    * ```js
95:    * import {isEnabled} from 'myModule';
96:    * export const MyComponent = isEnabled()
97:    *   ? <optimized version>
98:    *   : <original version>;
99:    * ```
100:    */
101:   dynamicGating: DynamicGatingOptions | null;
102: 
103:   panicThreshold: PanicThresholdOptions;
104: 
105:   /**
106:    * @deprecated
107:    *
108:    * When enabled, Forget will continue statically analyzing and linting code, but skip over codegen
109:    * passes.
110:    *
111:    * NOTE: ignored if `outputMode` is specified
112:    *
113:    * Defaults to false
114:    */
115:   noEmit: boolean;
116: 
117:   /**
118:    * If specified, overrides `noEmit` and controls the output mode of the compiler.
119:    *
120:    * Defaults to null
121:    */
122:   outputMode: CompilerOutputMode | null;
123: 
124:   /*
125:    * Determines the strategy for determining which functions to compile. Note that regardless of
126:    * which mode is enabled, a component can be opted out by adding the string literal
127:    * `"use no forget"` at the top of the function body, eg.:
128:    *
129:    * ```
130:    * function ComponentYouWantToSkipCompilation(props) {
131:    *    "use no forget";
132:    *    ...
133:    * }
134:    * ```
135:    */
136:   compilationMode: CompilationMode;
137: 
138:   /**
139:    * By default React Compiler will skip compilation of code that suppresses the default
140:    * React ESLint rules, since this is a strong indication that the code may be breaking React rules
141:    * in some way.
142:    *
143:    * Use eslintSuppressionRules to pass a custom set of rule names: any code which suppresses the
144:    * provided rules will skip compilation. To disable this feature (never bailout of compilation
145:    * even if the default ESLint is suppressed), pass an empty array.
146:    */
147:   eslintSuppressionRules: Array<string> | null | undefined;
148: 
149:   /**
150:    * Whether to report "suppression" errors for Flow suppressions. If false, suppression errors
151:    * are only emitted for ESLint suppressions
152:    */
153:   flowSuppressions: boolean;
154: 
155:   /*
156:    * Ignore 'use no forget' annotations. Helpful during testing but should not be used in production.
157:    */
158:   ignoreUseNoForget: boolean;
159: 
160:   /**
161:    * Unstable / do not use
162:    */
163:   customOptOutDirectives: CustomOptOutDirective;
164: 
165:   sources: Array<string> | ((filename: string) => boolean) | null;
166: 
167:   /**
168:    * The compiler has customized support for react-native-reanimated, intended as a temporary workaround.
169:    * Set this flag (on by default) to automatically check for this library and activate the support.
170:    */
171:   enableReanimatedCheck: boolean;
172: 
173:   /**
174:    * The minimum major version of React that the compiler should emit code for. If the target is 19
175:    * or higher, the compiler emits direct imports of React runtime APIs needed by the compiler. On
176:    * versions prior to 19, an extra runtime package react-compiler-runtime is necessary to provide
177:    * a userspace approximation of runtime APIs.
178:    */
179:   target: CompilerReactTarget;
180: }>;
181: 
182: export type ParsedPluginOptions = Required<
183:   Omit<PluginOptions, 'environment'>
184: > & {environment: EnvironmentConfig};
185: 
186: const CompilerReactTargetSchema = z.union([
187:   z.literal('17'),
188:   z.literal('18'),
189:   z.literal('19'),
190:   /**
191:    * Used exclusively for Meta apps which are guaranteed to have compatible
192:    * react runtime and compiler versions. Note that only the FB-internal bundles
193:    * re-export useMemoCache (see
194:    * https://github.com/facebook/react/blob/5b0ef217ef32333a8e56f39be04327c89efa346f/packages/react/index.fb.js#L68-L70),
195:    * so this option is invalid / creates runtime errors for open-source users.
196:    */
197:   z.object({
198:     kind: z.literal('donotuse_meta_internal'),
199:     runtimeModule: z.string().default('react'),
200:   }),
201: ]);
202: export type CompilerReactTarget = z.infer<typeof CompilerReactTargetSchema>;
203: 
204: const CompilationModeSchema = z.enum([
205:   /*
206:    * Compiles functions annotated with "use forget" or component/hook-like functions.
207:    * This latter includes:
208:    * * Components declared with component syntax.
209:    * * Functions which can be inferred to be a component or hook:
210:    *   - Be named like a hook or component. This logic matches the ESLint rule.
211:    *   - *and* create JSX and/or call a hook. This is an additional check to help prevent
212:    *     false positives, since compilation has a greater impact than linting.
213:    * This is the default mode
214:    */
215:   'infer',
216:   // Compile only components using Flow component syntax and hooks using hook syntax.
217:   'syntax',
218:   // Compile only functions which are explicitly annotated with "use forget"
219:   'annotation',
220:   // Compile all top-level functions
221:   'all',
222: ]);
223: 
224: export type CompilationMode = z.infer<typeof CompilationModeSchema>;
225: 
226: const CompilerOutputModeSchema = z.enum([
227:   // Build optimized for SSR, with client features removed
228:   'ssr',
229:   // Build optimized for the client, with auto memoization
230:   'client',
231:   // Build optimized for the client without auto memo
232:   'client-no-memo',
233:   // Lint mode, the output is unused but validations should run
234:   'lint',
235: ]);
236: 
237: export type CompilerOutputMode = z.infer<typeof CompilerOutputModeSchema>;
238: 
239: /**
240:  * Represents 'events' that may occur during compilation. Events are only
241:  * recorded when a logger is set (through the config).
242:  * These are the different types of events:
243:  * CompileError:
244:  *   Forget skipped compilation of a function / file due to a known todo,
245:  *   invalid input, or compiler invariant being broken.
246:  * CompileSuccess:
247:  *   Forget successfully compiled a function.
248:  * PipelineError:
249:  *   Unexpected errors that occurred during compilation (e.g. failures in
250:  *   babel or other unhandled exceptions).
251:  */
252: export type LoggerEvent =
253:   | CompileSuccessEvent
254:   | CompileErrorEvent
255:   | CompileDiagnosticEvent
256:   | CompileSkipEvent
257:   | PipelineErrorEvent
258:   | TimingEvent;
259: 
260: export type CompileErrorEvent = {
261:   kind: 'CompileError';
262:   fnLoc: t.SourceLocation | null;
263:   detail: CompilerErrorDetail | CompilerDiagnostic;
264: };
265: export type CompileDiagnosticEvent = {
266:   kind: 'CompileDiagnostic';
267:   fnLoc: t.SourceLocation | null;
268:   detail: Omit<Omit<CompilerErrorDetailOptions, 'severity'>, 'suggestions'>;
269: };
270: export type CompileSuccessEvent = {
271:   kind: 'CompileSuccess';
272:   fnLoc: t.SourceLocation | null;
273:   fnName: string | null;
274:   memoSlots: number;
275:   memoBlocks: number;
276:   memoValues: number;
277:   prunedMemoBlocks: number;
278:   prunedMemoValues: number;
279: };
280: export type CompileSkipEvent = {
281:   kind: 'CompileSkip';
282:   fnLoc: t.SourceLocation | null;
283:   reason: string;
284:   loc: t.SourceLocation | null;
285: };
286: export type PipelineErrorEvent = {
287:   kind: 'PipelineError';
288:   fnLoc: t.SourceLocation | null;
289:   data: string;
290: };
291: export type TimingEvent = {
292:   kind: 'Timing';
293:   measurement: PerformanceMeasure;
294: };
295: export type Logger = {
296:   logEvent: (filename: string | null, event: LoggerEvent) => void;
297:   debugLogIRs?: (value: CompilerPipelineValue) => void;
298: };
299: 
300: export const defaultOptions: ParsedPluginOptions = {
301:   compilationMode: 'infer',
302:   panicThreshold: 'none',
303:   environment: parseEnvironmentConfig({}).unwrap(),
304:   logger: null,
305:   gating: null,
306:   noEmit: false,
307:   outputMode: null,
308:   dynamicGating: null,
309:   eslintSuppressionRules: null,
310:   flowSuppressions: true,
311:   ignoreUseNoForget: false,
312:   sources: filename => {
313:     return filename.indexOf('node_modules') === -1;
314:   },
315:   enableReanimatedCheck: true,
316:   customOptOutDirectives: null,
317:   target: '19',
318: };
319: 
320: export function parsePluginOptions(obj: unknown): ParsedPluginOptions {
321:   if (obj == null || typeof obj !== 'object') {
322:     return defaultOptions;
323:   }
324:   const parsedOptions = Object.create(null);
325:   for (let [key, value] of Object.entries(obj)) {
326:     if (typeof value === 'string') {
327:       // normalize string configs to be case insensitive
328:       value = value.toLowerCase();
329:     }
330:     if (isCompilerFlag(key)) {
331:       switch (key) {
332:         case 'environment': {
333:           const environmentResult = parseEnvironmentConfig(value);
334:           if (environmentResult.isErr()) {
335:             CompilerError.throwInvalidConfig({
336:               reason:
337:                 'Error in validating environment config. This is an advanced setting and not meant to be used directly',
338:               description: environmentResult.unwrapErr().toString(),
339:               suggestions: null,
340:               loc: null,
341:             });
342:           }
343:           parsedOptions[key] = environmentResult.unwrap();
344:           break;
