192:    * react runtime and compiler versions. Note that only the FB-internal bundles
193:    * re-export useMemoCache (see
194:    * https://github.com/facebook/react/blob/5b0ef217ef32333a8e56f39be04327c89efa346f/packages/react/index.fb.js#L68-L70),
195:    * so this option is invalid / creates runtime errors for open-source users.
196:    */
197:   z.object({
198:     kind: z.literal('donotuse_meta_internal'),
199:     runtimeModule: z.string().default('react'),
200:   }),
201: ]);
202: export type CompilerReactTarget = z.infer<typeof CompilerReactTargetSchema>;
203: 
204: const CompilationModeSchema = z.enum([
205:   /*
206:    * Compiles functions annotated with "use forget" or component/hook-like functions.
207:    * This latter includes:
208:    * * Components declared with component syntax.
209:    * * Functions which can be inferred to be a component or hook:
210:    *   - Be named like a hook or component. This logic matches the ESLint rule.
211:    *   - *and* create JSX and/or call a hook. This is an additional check to help prevent
212:    *     false positives, since compilation has a greater impact than linting.
213:    * This is the default mode
214:    */
215:   'infer',
216:   // Compile only components using Flow component syntax and hooks using hook syntax.
217:   'syntax',
218:   // Compile only functions which are explicitly annotated with "use forget"
219:   'annotation',
220:   // Compile all top-level functions
221:   'all',
222: ]);
