239: /**
240:  * Represents 'events' that may occur during compilation. Events are only
241:  * recorded when a logger is set (through the config).
242:  * These are the different types of events:
243:  * CompileError:
244:  *   Forget skipped compilation of a function / file due to a known todo,
245:  *   invalid input, or compiler invariant being broken.
246:  * CompileSuccess:
247:  *   Forget successfully compiled a function.
248:  * PipelineError:
249:  *   Unexpected errors that occurred during compilation (e.g. failures in
250:  *   babel or other unhandled exceptions).
251:  */
252: export type LoggerEvent =
253:   | CompileSuccessEvent
254:   | CompileErrorEvent
255:   | CompileDiagnosticEvent
256:   | CompileSkipEvent
257:   | PipelineErrorEvent
258:   | TimingEvent;
