260: export type CompileErrorEvent = {
261:   kind: 'CompileError';
262:   fnLoc: t.SourceLocation | null;
263:   detail: CompilerErrorDetail | CompilerDiagnostic;
264: };
265: export type CompileDiagnosticEvent = {
266:   kind: 'CompileDiagnostic';
