268:   detail: Omit<Omit<CompilerErrorDetailOptions, 'severity'>, 'suggestions'>;
269: };
270: export type CompileSuccessEvent = {
271:   kind: 'CompileSuccess';
272:   fnLoc: t.SourceLocation | null;
273:   fnName: string | null;
274:   memoSlots: number;
275:   memoBlocks: number;
276:   memoValues: number;
277:   prunedMemoBlocks: number;
278:   prunedMemoValues: number;
279: };
280: export type CompileSkipEvent = {
281:   kind: 'CompileSkip';
282:   fnLoc: t.SourceLocation | null;
283:   reason: string;
284:   loc: t.SourceLocation | null;
285: };
286: export type PipelineErrorEvent = {
287:   kind: 'PipelineError';
288:   fnLoc: t.SourceLocation | null;
289:   data: string;
290: };
291: export type TimingEvent = {
292:   kind: 'Timing';
293:   measurement: PerformanceMeasure;
294: };
295: export type Logger = {
296:   logEvent: (filename: string | null, event: LoggerEvent) => void;
297:   debugLogIRs?: (value: CompilerPipelineValue) => void;
298: };
