300: export const defaultOptions: ParsedPluginOptions = {
301:   compilationMode: 'infer',
302:   panicThreshold: 'none',
303:   environment: parseEnvironmentConfig({}).unwrap(),
304:   logger: null,
305:   gating: null,
306:   noEmit: false,
307:   outputMode: null,
308:   dynamicGating: null,
309:   eslintSuppressionRules: null,
310:   flowSuppressions: true,
311:   ignoreUseNoForget: false,
312:   sources: filename => {
313:     return filename.indexOf('node_modules') === -1;
314:   },
315:   enableReanimatedCheck: true,
316:   customOptOutDirectives: null,
317:   target: '19',
318: };
319: 
320: export function parsePluginOptions(obj: unknown): ParsedPluginOptions {
321:   if (obj == null || typeof obj !== 'object') {
322:     return defaultOptions;
323:   }
324:   const parsedOptions = Object.create(null);
325:   for (let [key, value] of Object.entries(obj)) {
326:     if (typeof value === 'string') {
327:       // normalize string configs to be case insensitive
328:       value = value.toLowerCase();
329:     }
330:     if (isCompilerFlag(key)) {
331:       switch (key) {
332:         case 'environment': {
333:           const environmentResult = parseEnvironmentConfig(value);
334:           if (environmentResult.isErr()) {
335:             CompilerError.throwInvalidConfig({
336:               reason:
337:                 'Error in validating environment config. This is an advanced setting and not meant to be used directly',
338:               description: environmentResult.unwrapErr().toString(),
339:               suggestions: null,
340:               loc: null,
341:             });
342:           }
343:           parsedOptions[key] = environmentResult.unwrap();
344:           break;
345:         }
346:         case 'target': {
347:           parsedOptions[key] = parseTargetConfig(value);
348:           break;
349:         }
350:         case 'gating': {
351:           if (value == null) {
352:             parsedOptions[key] = null;
353:           } else {
354:             parsedOptions[key] = tryParseExternalFunction(value);
355:           }
356:           break;
357:         }
358:         case 'dynamicGating': {
359:           if (value == null) {
360:             parsedOptions[key] = null;
361:           } else {
362:             const result = DynamicGatingOptionsSchema.safeParse(value);
363:             if (result.success) {
364:               parsedOptions[key] = result.data;
365:             } else {
366:               CompilerError.throwInvalidConfig({
367:                 reason:
368:                   'Could not parse dynamic gating. Update React Compiler config to fix the error',
369:                 description: `${fromZodError(result.error)}`,
370:                 loc: null,
371:                 suggestions: null,
372:               });
373:             }
374:           }
375:           break;
376:         }
377:         case 'customOptOutDirectives': {
378:           const result = CustomOptOutDirectiveSchema.safeParse(value);
379:           if (result.success) {
380:             parsedOptions[key] = result.data;
381:           } else {
382:             CompilerError.throwInvalidConfig({
383:               reason:
384:                 'Could not parse custom opt out directives. Update React Compiler config to fix the error',
385:               description: `${fromZodError(result.error)}`,
386:               loc: null,
387:               suggestions: null,
388:             });
389:           }
390:           break;
391:         }
392:         default: {
393:           parsedOptions[key] = value;
394:         }
395:       }
396:     }
397:   }
398:   return {...defaultOptions, ...parsedOptions};
399: }
400: 
401: export function parseTargetConfig(value: unknown): CompilerReactTarget {
402:   const parsed = CompilerReactTargetSchema.safeParse(value);
403:   if (parsed.success) {
404:     return parsed.data;
405:   } else {
406:     CompilerError.throwInvalidConfig({
407:       reason: 'Not a valid target',
408:       description: `${fromZodError(parsed.error)}`,
409:       suggestions: null,
410:       loc: null,
411:     });
412:   }
413: }
414: 
415: function isCompilerFlag(s: string): s is keyof PluginOptions {
416:   return hasOwnProperty(defaultOptions, s);
417: }
