41: export type CompilerPass = {
42:   opts: ParsedPluginOptions;
43:   filename: string | null;
44:   comments: Array<t.CommentBlock | t.CommentLine>;
45:   code: string | null;
46: };
47: export const OPT_IN_DIRECTIVES = new Set(['use forget', 'use memo']);
48: export const OPT_OUT_DIRECTIVES = new Set(['use no forget', 'use no memo']);
49: const DYNAMIC_GATING_DIRECTIVE = new RegExp('^use memo if\\(([^\\)]*)\\)$');
50: 
51: export function tryFindDirectiveEnablingMemoization(
52:   directives: Array<t.Directive>,
53:   opts: ParsedPluginOptions,
54: ): Result<t.Directive | null, CompilerError> {
55:   const optIn = directives.find(directive =>
56:     OPT_IN_DIRECTIVES.has(directive.value.value),
57:   );
58:   if (optIn != null) {
59:     return Ok(optIn);
60:   }
61:   const dynamicGating = findDirectivesDynamicGating(directives, opts);
62:   if (dynamicGating.isOk()) {
63:     return Ok(dynamicGating.unwrap()?.directive ?? null);
64:   } else {
65:     return Err(dynamicGating.unwrapErr());
66:   }
67: }
68: 
69: export function findDirectiveDisablingMemoization(
70:   directives: Array<t.Directive>,
71:   {customOptOutDirectives}: PluginOptions,
72: ): t.Directive | null {
73:   if (customOptOutDirectives != null) {
74:     return (
75:       directives.find(
76:         directive =>
77:           customOptOutDirectives.indexOf(directive.value.value) !== -1,
78:       ) ?? null
79:     );
80:   }
81:   return (
82:     directives.find(directive =>
83:       OPT_OUT_DIRECTIVES.has(directive.value.value),
84:     ) ?? null
85:   );
86: }
87: function findDirectivesDynamicGating(
88:   directives: Array<t.Directive>,
89:   opts: ParsedPluginOptions,
90: ): Result<
91:   {
92:     gating: ExternalFunction;
93:     directive: t.Directive;
94:   } | null,
95:   CompilerError
96: > {
97:   if (opts.dynamicGating === null) {
98:     return Ok(null);
99:   }
100:   const errors = new CompilerError();
101:   const result: Array<{directive: t.Directive; match: string}> = [];
102: 
103:   for (const directive of directives) {
104:     const maybeMatch = DYNAMIC_GATING_DIRECTIVE.exec(directive.value.value);
105:     if (maybeMatch != null && maybeMatch[1] != null) {
106:       if (t.isValidIdentifier(maybeMatch[1])) {
107:         result.push({directive, match: maybeMatch[1]});
108:       } else {
109:         errors.push({
110:           reason: `Dynamic gating directive is not a valid JavaScript identifier`,
111:           description: `Found '${directive.value.value}'`,
112:           category: ErrorCategory.Gating,
113:           loc: directive.loc ?? null,
114:           suggestions: null,
115:         });
116:       }
117:     }
118:   }
119:   if (errors.hasAnyErrors()) {
120:     return Err(errors);
121:   } else if (result.length > 1) {
122:     const error = new CompilerError();
123:     error.push({
124:       reason: `Multiple dynamic gating directives found`,
125:       description: `Expected a single directive but found [${result
126:         .map(r => r.directive.value.value)
127:         .join(', ')}]`,
128:       category: ErrorCategory.Gating,
129:       loc: result[0].directive.loc ?? null,
130:       suggestions: null,
131:     });
132:     return Err(error);
133:   } else if (result.length === 1) {
134:     return Ok({
135:       gating: {
136:         source: opts.dynamicGating.source,
137:         importSpecifierName: result[0].match,
138:       },
139:       directive: result[0].directive,
140:     });
141:   } else {
142:     return Ok(null);
143:   }
144: }
