224: export function createNewFunctionNode(
225:   originalFn: BabelFn,
226:   compiledFn: CodegenFunction,
227: ): t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression {
228:   let transformedFn:
229:     | t.FunctionDeclaration
230:     | t.ArrowFunctionExpression
231:     | t.FunctionExpression;
232:   switch (originalFn.node.type) {
233:     case 'FunctionDeclaration': {
234:       const fn: t.FunctionDeclaration = {
235:         type: 'FunctionDeclaration',
236:         id: compiledFn.id,
237:         loc: originalFn.node.loc ?? null,
238:         async: compiledFn.async,
239:         generator: compiledFn.generator,
240:         params: compiledFn.params,
241:         body: compiledFn.body,
242:       };
243:       transformedFn = fn;
244:       break;
245:     }
246:     case 'ArrowFunctionExpression': {
247:       const fn: t.ArrowFunctionExpression = {
248:         type: 'ArrowFunctionExpression',
249:         loc: originalFn.node.loc ?? null,
250:         async: compiledFn.async,
251:         generator: compiledFn.generator,
252:         params: compiledFn.params,
253:         expression: originalFn.node.expression,
254:         body: compiledFn.body,
255:       };
256:       transformedFn = fn;
257:       break;
258:     }
259:     case 'FunctionExpression': {
260:       const fn: t.FunctionExpression = {
261:         type: 'FunctionExpression',
262:         id: compiledFn.id,
263:         loc: originalFn.node.loc ?? null,
264:         async: compiledFn.async,
265:         generator: compiledFn.generator,
266:         params: compiledFn.params,
267:         body: compiledFn.body,
268:       };
269:       transformedFn = fn;
270:       break;
271:     }
272:     default: {
273:       assertExhaustive(
274:         originalFn.node,
275:         `Creating unhandled function: ${originalFn.node}`,
276:       );
277:     }
278:   }
279:   // Avoid visiting the new transformed version
280:   return transformedFn;
281: }
282: 
283: function insertNewOutlinedFunctionNode(
284:   program: NodePath<t.Program>,
285:   originalFn: BabelFn,
286:   compiledFn: CodegenFunction,
287: ): BabelFn {
288:   switch (originalFn.type) {
289:     case 'FunctionDeclaration': {
290:       return originalFn.insertAfter(
291:         createNewFunctionNode(originalFn, compiledFn),
292:       )[0]!;
293:     }
294:     /**
295:      * We can't just append the outlined function as a sibling of the original function if it is an
296:      * (Arrow)FunctionExpression parented by a VariableDeclaration, as this would cause its parent
297:      * to become a SequenceExpression instead which breaks a bunch of assumptions elsewhere in the
298:      * plugin.
299:      *
300:      * To get around this, we always synthesize a new FunctionDeclaration for the outlined function
301:      * and insert it as a true sibling to the original function.
302:      */
303:     case 'ArrowFunctionExpression':
304:     case 'FunctionExpression': {
305:       const fn: t.FunctionDeclaration = {
306:         type: 'FunctionDeclaration',
307:         id: compiledFn.id,
308:         loc: originalFn.node.loc ?? null,
309:         async: compiledFn.async,
310:         generator: compiledFn.generator,
311:         params: compiledFn.params,
312:         body: compiledFn.body,
313:       };
314:       const insertedFuncDecl = program.pushContainer('body', [fn])[0]!;
315:       CompilerError.invariant(insertedFuncDecl.isFunctionDeclaration(), {
316:         reason: 'Expected inserted function declaration',
317:         description: `Got: ${insertedFuncDecl}`,
318:         loc: insertedFuncDecl.node?.loc ?? GeneratedSource,
319:       });
320:       return insertedFuncDecl;
321:     }
322:     default: {
323:       assertExhaustive(
324:         originalFn,
325:         `Inserting unhandled function: ${originalFn}`,
326:       );
327:     }
328:   }
329: }
