492: type CompileSource = {
493:   kind: 'original' | 'outlined';
494:   fn: BabelFn;
495:   fnType: ReactFunctionType;
496: };
497: /**
498:  * Find all React components and hooks that need to be compiled
499:  *
500:  * @returns An array of React functions from @param program to transform
501:  */
502: function findFunctionsToCompile(
503:   program: NodePath<t.Program>,
504:   pass: CompilerPass,
505:   programContext: ProgramContext,
506: ): Array<CompileSource> {
507:   const queue: Array<CompileSource> = [];
508:   const traverseFunction = (fn: BabelFn, pass: CompilerPass): void => {
509:     // In 'all' mode, compile only top level functions
510:     if (
511:       pass.opts.compilationMode === 'all' &&
512:       fn.scope.getProgramParent() !== fn.scope.parent
513:     ) {
514:       return;
515:     }
516: 
517:     const fnType = getReactFunctionType(fn, pass);
518: 
519:     if (fnType === null || programContext.alreadyCompiled.has(fn.node)) {
520:       return;
521:     }
522: 
523:     /*
524:      * We may be generating a new FunctionDeclaration node, so we must skip over it or this
525:      * traversal will loop infinitely.
526:      * Ensure we avoid visiting the original function again.
527:      */
528:     programContext.alreadyCompiled.add(fn.node);
529:     fn.skip();
530: 
531:     queue.push({kind: 'original', fn, fnType});
532:   };
533: 
534:   // Main traversal to compile with Forget
535:   program.traverse(
536:     {
537:       ClassDeclaration(node: NodePath<t.ClassDeclaration>) {
538:         /*
539:          * Don't visit functions defined inside classes, because they
540:          * can reference `this` which is unsafe for compilation
541:          */
542:         node.skip();
543:       },
544: 
545:       ClassExpression(node: NodePath<t.ClassExpression>) {
546:         /*
547:          * Don't visit functions defined inside classes, because they
548:          * can reference `this` which is unsafe for compilation
549:          */
550:         node.skip();
551:       },
552: 
553:       FunctionDeclaration: traverseFunction,
554: 
555:       FunctionExpression: traverseFunction,
556: 
557:       ArrowFunctionExpression: traverseFunction,
558:     },
559:     {
560:       ...pass,
561:       opts: {...pass.opts, ...pass.opts},
562:       filename: pass.filename ?? null,
563:     },
564:   );
565:   return queue;
566: }
