568: /**
569:  * Try to compile a source function, taking into account all local suppressions,
570:  * opt-ins, and opt-outs.
571:  *
572:  * Errors encountered during compilation are either logged (if recoverable) or
573:  * thrown (if non-recoverable).
574:  *
575:  * @returns the compiled function or null if the function was skipped (due to
576:  * config settings and/or outputs)
577:  */
578: function processFn(
579:   fn: BabelFn,
580:   fnType: ReactFunctionType,
581:   programContext: ProgramContext,
582:   outputMode: CompilerOutputMode,
583: ): null | CodegenFunction {
584:   let directives: {
585:     optIn: t.Directive | null;
586:     optOut: t.Directive | null;
587:   };
588:   if (fn.node.body.type !== 'BlockStatement') {
589:     directives = {
590:       optIn: null,
591:       optOut: null,
592:     };
593:   } else {
594:     const optIn = tryFindDirectiveEnablingMemoization(
595:       fn.node.body.directives,
596:       programContext.opts,
597:     );
598:     if (optIn.isErr()) {
599:       /**
600:        * If parsing opt-in directive fails, it's most likely that React Compiler
601:        * was not tested or rolled out on this function. In that case, we handle
602:        * the error and fall back to the safest option which is to not optimize
603:        * the function.
604:        */
605:       handleError(optIn.unwrapErr(), programContext, fn.node.loc ?? null);
606:       return null;
607:     }
608:     directives = {
609:       optIn: optIn.unwrapOr(null),
610:       optOut: findDirectiveDisablingMemoization(
611:         fn.node.body.directives,
612:         programContext.opts,
613:       ),
614:     };
615:   }
616: 
617:   let compiledFn: CodegenFunction;
618:   const compileResult = tryCompileFunction(
619:     fn,
620:     fnType,
621:     programContext,
622:     outputMode,
623:   );
624:   if (compileResult.kind === 'error') {
625:     if (directives.optOut != null) {
626:       logError(compileResult.error, programContext, fn.node.loc ?? null);
627:     } else {
628:       handleError(compileResult.error, programContext, fn.node.loc ?? null);
629:     }
630:     return null;
631:   } else {
632:     compiledFn = compileResult.compiledFn;
633:   }
634: 
635:   /**
636:    * If 'use no forget/memo' is present and we still ran the code through the
637:    * compiler for validation, log a skip event and don't mutate the babel AST.
638:    * This allows us to flag if there is an unused 'use no forget/memo'
639:    * directive.
640:    */
641:   if (
642:     programContext.opts.ignoreUseNoForget === false &&
643:     directives.optOut != null
644:   ) {
645:     programContext.logEvent({
646:       kind: 'CompileSkip',
647:       fnLoc: fn.node.body.loc ?? null,
648:       reason: `Skipped due to '${directives.optOut.value}' directive.`,
649:       loc: directives.optOut.loc ?? null,
650:     });
651:     return null;
652:   }
653:   programContext.logEvent({
654:     kind: 'CompileSuccess',
655:     fnLoc: fn.node.loc ?? null,
656:     fnName: compiledFn.id?.name ?? null,
657:     memoSlots: compiledFn.memoSlotsUsed,
658:     memoBlocks: compiledFn.memoBlocks,
659:     memoValues: compiledFn.memoValues,
660:     prunedMemoBlocks: compiledFn.prunedMemoBlocks,
661:     prunedMemoValues: compiledFn.prunedMemoValues,
662:   });
663: 
664:   if (programContext.hasModuleScopeOptOut) {
665:     return null;
666:   } else if (programContext.opts.outputMode === 'lint') {
667:     return null;
668:   } else if (
669:     programContext.opts.compilationMode === 'annotation' &&
670:     directives.optIn == null
671:   ) {
672:     /**
673:      * If no opt-in directive is found and the compiler is configured in
674:      * annotation mode, don't insert the compiled function.
675:      */
676:     return null;
677:   } else {
678:     return compiledFn;
679:   }
680: }
681: 
682: function tryCompileFunction(
683:   fn: BabelFn,
684:   fnType: ReactFunctionType,
685:   programContext: ProgramContext,
686:   outputMode: CompilerOutputMode,
687: ):
688:   | {kind: 'compile'; compiledFn: CodegenFunction}
689:   | {kind: 'error'; error: unknown} {
690:   /**
691:    * Note that Babel does not attach comment nodes to nodes; they are dangling off of the
692:    * Program node itself. We need to figure out whether an eslint suppression range
693:    * applies to this function first.
694:    */
695:   const suppressionsInFunction = filterSuppressionsThatAffectFunction(
696:     programContext.suppressions,
697:     fn,
698:   );
699:   if (suppressionsInFunction.length > 0) {
700:     return {
701:       kind: 'error',
702:       error: suppressionsToCompilerError(suppressionsInFunction),
703:     };
704:   }
705: 
706:   try {
707:     return {
708:       kind: 'compile',
709:       compiledFn: compileFn(
710:         fn,
711:         programContext.opts.environment,
712:         fnType,
713:         outputMode,
714:         programContext,
715:         programContext.opts.logger,
716:         programContext.filename,
717:         programContext.code,
718:       ),
719:     };
720:   } catch (err) {
721:     return {kind: 'error', error: err};
722:   }
723: }
