809: function getReactFunctionType(
810:   fn: BabelFn,
811:   pass: CompilerPass,
812: ): ReactFunctionType | null {
813:   if (fn.node.body.type === 'BlockStatement') {
814:     const optInDirectives = tryFindDirectiveEnablingMemoization(
815:       fn.node.body.directives,
816:       pass.opts,
817:     );
818:     if (optInDirectives.unwrapOr(null) != null) {
819:       return getComponentOrHookLike(fn) ?? 'Other';
820:     }
821:   }
822: 
823:   // Component and hook declarations are known components/hooks
824:   let componentSyntaxType: ReactFunctionType | null = null;
825:   if (fn.isFunctionDeclaration()) {
826:     if (isComponentDeclaration(fn.node)) {
827:       componentSyntaxType = 'Component';
828:     } else if (isHookDeclaration(fn.node)) {
829:       componentSyntaxType = 'Hook';
830:     }
831:   }
832: 
833:   switch (pass.opts.compilationMode) {
834:     case 'annotation': {
835:       // opt-ins are checked above
836:       return null;
837:     }
838:     case 'infer': {
839:       // Check if this is a component or hook-like function
840:       return componentSyntaxType ?? getComponentOrHookLike(fn);
841:     }
842:     case 'syntax': {
843:       return componentSyntaxType;
844:     }
845:     case 'all': {
846:       return getComponentOrHookLike(fn) ?? 'Other';
847:     }
848:     default: {
849:       assertExhaustive(
850:         pass.opts.compilationMode,
851:         `Unexpected compilationMode \`${pass.opts.compilationMode}\``,
852:       );
853:     }
854:   }
855: }
