857: /**
858:  * Returns true if the program contains an `import {c} from "<moduleName>"` declaration,
859:  * regardless of the local name of the 'c' specifier and the presence of other specifiers
860:  * in the same declaration.
861:  */
862: function hasMemoCacheFunctionImport(
863:   program: NodePath<t.Program>,
864:   moduleName: string,
865: ): boolean {
866:   let hasUseMemoCache = false;
867:   program.traverse({
868:     ImportSpecifier(path) {
869:       const imported = path.get('imported');
870:       let importedName: string | null = null;
871:       if (imported.isIdentifier()) {
872:         importedName = imported.node.name;
873:       } else if (imported.isStringLiteral()) {
874:         importedName = imported.node.value;
875:       }
876:       if (
877:         importedName === 'c' &&
878:         path.parentPath.isImportDeclaration() &&
879:         path.parentPath.get('source').node.value === moduleName
880:       ) {
881:         hasUseMemoCache = true;
882:       }
883:     },
884:   });
885:   return hasUseMemoCache;
886: }
