888: function isHookName(s: string): boolean {
889:   return /^use[A-Z0-9]/.test(s);
890: }
891: 
892: /*
893:  * We consider hooks to be a hook name identifier or a member expression
894:  * containing a hook name.
895:  */
896: 
897: function isHook(path: NodePath<t.Expression | t.PrivateName>): boolean {
898:   if (path.isIdentifier()) {
899:     return isHookName(path.node.name);
900:   } else if (
901:     path.isMemberExpression() &&
902:     !path.node.computed &&
903:     isHook(path.get('property'))
904:   ) {
905:     const obj = path.get('object').node;
906:     const isPascalCaseNameSpace = /^[A-Z].*/;
907:     return obj.type === 'Identifier' && isPascalCaseNameSpace.test(obj.name);
908:   } else {
909:     return false;
910:   }
911: }
912: 
913: /*
914:  * Checks if the node is a React component name. React component names must
915:  * always start with an uppercase letter.
916:  */
917: 
918: function isComponentName(path: NodePath<t.Expression>): boolean {
919:   return path.isIdentifier() && /^[A-Z]/.test(path.node.name);
920: }
