725: /**
726:  * Applies React Compiler generated functions to the babel AST by replacing
727:  * existing functions in place or inserting new declarations.
728:  */
729: function applyCompiledFunctions(
730:   program: NodePath<t.Program>,
731:   compiledFns: Array<CompileResult>,
732:   pass: CompilerPass,
733:   programContext: ProgramContext,
734: ): void {
735:   let referencedBeforeDeclared = null;
736:   for (const result of compiledFns) {
737:     const {kind, originalFn, compiledFn} = result;
738:     const transformedFn = createNewFunctionNode(originalFn, compiledFn);
739:     programContext.alreadyCompiled.add(transformedFn);
740: 
741:     let dynamicGating: ExternalFunction | null = null;
742:     if (originalFn.node.body.type === 'BlockStatement') {
743:       const result = findDirectivesDynamicGating(
744:         originalFn.node.body.directives,
745:         pass.opts,
746:       );
747:       if (result.isOk()) {
748:         dynamicGating = result.unwrap()?.gating ?? null;
749:       }
750:     }
751:     const functionGating = dynamicGating ?? pass.opts.gating;
752:     if (kind === 'original' && functionGating != null) {
753:       referencedBeforeDeclared ??=
754:         getFunctionReferencedBeforeDeclarationAtTopLevel(program, compiledFns);
755:       insertGatedFunctionDeclaration(
756:         originalFn,
757:         transformedFn,
758:         programContext,
759:         functionGating,
760:         referencedBeforeDeclared.has(result),
761:       );
762:     } else {
763:       originalFn.replaceWith(transformedFn);
764:     }
765:   }
766: 
767:   // Forget compiled the component, we need to update existing imports of useMemoCache
768:   if (compiledFns.length > 0) {
769:     addImportsToProgram(program, programContext);
770:   }
771: }
