773: function shouldSkipCompilation(
774:   program: NodePath<t.Program>,
775:   pass: CompilerPass,
776: ): boolean {
777:   if (pass.opts.sources) {
778:     if (pass.filename === null) {
779:       const error = new CompilerError();
780:       error.pushErrorDetail(
781:         new CompilerErrorDetail({
782:           reason: `Expected a filename but found none.`,
783:           description:
784:             "When the 'sources' config options is specified, the React compiler will only compile files with a name",
785:           category: ErrorCategory.Config,
786:           loc: null,
787:         }),
788:       );
789:       handleError(error, pass, null);
790:       return true;
791:     }
792: 
793:     if (!isFilePartOfSources(pass.opts.sources, pass.filename)) {
794:       return true;
795:     }
796:   }
797: 
798:   if (
799:     hasMemoCacheFunctionImport(
800:       program,
801:       getReactCompilerRuntimeModule(pass.opts.target),
802:     )
803:   ) {
804:     return true;
805:   }
806:   return false;
807: }
