888: function isHookName(s: string): boolean {
889:   return /^use[A-Z0-9]/.test(s);
890: }
891: 
892: /*
893:  * We consider hooks to be a hook name identifier or a member expression
894:  * containing a hook name.
895:  */
896: 
897: function isHook(path: NodePath<t.Expression | t.PrivateName>): boolean {
898:   if (path.isIdentifier()) {
899:     return isHookName(path.node.name);
900:   } else if (
901:     path.isMemberExpression() &&
902:     !path.node.computed &&
903:     isHook(path.get('property'))
904:   ) {
905:     const obj = path.get('object').node;
906:     const isPascalCaseNameSpace = /^[A-Z].*/;
907:     return obj.type === 'Identifier' && isPascalCaseNameSpace.test(obj.name);
908:   } else {
909:     return false;
910:   }
911: }
912: 
913: /*
914:  * Checks if the node is a React component name. React component names must
915:  * always start with an uppercase letter.
916:  */
917: 
918: function isComponentName(path: NodePath<t.Expression>): boolean {
919:   return path.isIdentifier() && /^[A-Z]/.test(path.node.name);
920: }
921: 
922: function isReactAPI(
923:   path: NodePath<t.Expression | t.PrivateName | t.V8IntrinsicIdentifier>,
924:   functionName: string,
925: ): boolean {
926:   const node = path.node;
927:   return (
928:     (node.type === 'Identifier' && node.name === functionName) ||
929:     (node.type === 'MemberExpression' &&
930:       node.object.type === 'Identifier' &&
931:       node.object.name === 'React' &&
932:       node.property.type === 'Identifier' &&
933:       node.property.name === functionName)
934:   );
935: }
936: 
937: /*
938:  * Checks if the node is a callback argument of forwardRef. This render function
939:  * should follow the rules of hooks.
940:  */
941: 
942: function isForwardRefCallback(path: NodePath<t.Expression>): boolean {
943:   return !!(
944:     path.parentPath.isCallExpression() &&
945:     path.parentPath.get('callee').isExpression() &&
946:     isReactAPI(path.parentPath.get('callee'), 'forwardRef')
947:   );
948: }
949: 
950: /*
951:  * Checks if the node is a callback argument of React.memo. This anonymous
952:  * functional component should follow the rules of hooks.
953:  */
954: 
955: function isMemoCallback(path: NodePath<t.Expression>): boolean {
956:   return (
957:     path.parentPath.isCallExpression() &&
958:     path.parentPath.get('callee').isExpression() &&
959:     isReactAPI(path.parentPath.get('callee'), 'memo')
960:   );
961: }
