963: function isValidPropsAnnotation(
964:   annot: t.TypeAnnotation | t.TSTypeAnnotation | t.Noop | null | undefined,
965: ): boolean {
966:   if (annot == null) {
967:     return true;
968:   } else if (annot.type === 'TSTypeAnnotation') {
969:     switch (annot.typeAnnotation.type) {
970:       case 'TSArrayType':
971:       case 'TSBigIntKeyword':
972:       case 'TSBooleanKeyword':
973:       case 'TSConstructorType':
974:       case 'TSFunctionType':
975:       case 'TSLiteralType':
976:       case 'TSNeverKeyword':
977:       case 'TSNumberKeyword':
978:       case 'TSStringKeyword':
979:       case 'TSSymbolKeyword':
980:       case 'TSTupleType':
981:         return false;
982:     }
983:     return true;
984:   } else if (annot.type === 'TypeAnnotation') {
985:     switch (annot.typeAnnotation.type) {
986:       case 'ArrayTypeAnnotation':
987:       case 'BooleanLiteralTypeAnnotation':
988:       case 'BooleanTypeAnnotation':
989:       case 'EmptyTypeAnnotation':
990:       case 'FunctionTypeAnnotation':
991:       case 'NumberLiteralTypeAnnotation':
992:       case 'NumberTypeAnnotation':
993:       case 'StringLiteralTypeAnnotation':
994:       case 'StringTypeAnnotation':
995:       case 'SymbolTypeAnnotation':
996:       case 'ThisTypeAnnotation':
997:       case 'TupleTypeAnnotation':
998:         return false;
999:     }
1000:     return true;
1001:   } else if (annot.type === 'Noop') {
1002:     return true;
1003:   } else {
1004:     assertExhaustive(annot, `Unexpected annotation node \`${annot}\``);
1005:   }
1006: }
