1008: function isValidComponentParams(
1009:   params: Array<NodePath<t.Identifier | t.Pattern | t.RestElement>>,
1010: ): boolean {
1011:   if (params.length === 0) {
1012:     return true;
1013:   } else if (params.length > 0 && params.length <= 2) {
1014:     if (!isValidPropsAnnotation(params[0].node.typeAnnotation)) {
1015:       return false;
1016:     }
1017: 
1018:     if (params.length === 1) {
1019:       return !params[0].isRestElement();
1020:     } else if (params[1].isIdentifier()) {
1021:       // check if second param might be a ref
1022:       const {name} = params[1].node;
1023:       return name.includes('ref') || name.includes('Ref');
1024:     } else {
1025:       /**
1026:        * Otherwise, avoid helper functions that take more than one argument.
1027:        * Helpers are _usually_ named with lowercase, but some code may
1028:        * violate this rule
1029:        */
1030:       return false;
1031:     }
1032:   }
1033:   return false;
1034: }
1035: 
1036: /*
1037:  * Adapted from the ESLint rule at
1038:  * https://github.com/facebook/react/blob/main/packages/eslint-plugin-react-hooks/src/RulesOfHooks.js#L90-L103
1039:  */
1040: function getComponentOrHookLike(
1041:   node: NodePath<
1042:     t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
1043:   >,
1044: ): ReactFunctionType | null {
1045:   const functionName = getFunctionName(node);
1046:   // Check if the name is component or hook like:
1047:   if (functionName !== null && isComponentName(functionName)) {
1048:     let isComponent =
1049:       callsHooksOrCreatesJsx(node) &&
1050:       isValidComponentParams(node.get('params')) &&
1051:       !returnsNonNode(node);
1052:     return isComponent ? 'Component' : null;
1053:   } else if (functionName !== null && isHook(functionName)) {
1054:     // Hooks have hook invocations or JSX, but can take any # of arguments
1055:     return callsHooksOrCreatesJsx(node) ? 'Hook' : null;
1056:   }
1057: 
1058:   /*
1059:    * Otherwise for function or arrow function expressions, check if they
1060:    * appear as the argument to React.forwardRef() or React.memo():
1061:    */
1062:   if (node.isFunctionExpression() || node.isArrowFunctionExpression()) {
1063:     if (isForwardRefCallback(node) || isMemoCallback(node)) {
1064:       // As an added check we also look for hook invocations or JSX
1065:       return callsHooksOrCreatesJsx(node) ? 'Component' : null;
1066:     }
1067:   }
1068:   return null;
1069: }
1070: 
1071: function skipNestedFunctions(
1072:   node: NodePath<
1073:     t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
1074:   >,
1075: ) {
1076:   return (
1077:     fn: NodePath<
1078:       t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
1079:     >,
1080:   ): void => {
1081:     if (fn.node !== node.node) {
1082:       fn.skip();
1083:     }
1084:   };
1085: }
1086: 
1087: function callsHooksOrCreatesJsx(
1088:   node: NodePath<
1089:     t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
1090:   >,
1091: ): boolean {
1092:   let invokesHooks = false;
1093:   let createsJsx = false;
1094: 
1095:   node.traverse({
1096:     JSX() {
1097:       createsJsx = true;
1098:     },
1099:     CallExpression(call) {
1100:       const callee = call.get('callee');
1101:       if (callee.isExpression() && isHook(callee)) {
1102:         invokesHooks = true;
1103:       }
1104:     },
1105:     ArrowFunctionExpression: skipNestedFunctions(node),
1106:     FunctionExpression: skipNestedFunctions(node),
1107:     FunctionDeclaration: skipNestedFunctions(node),
1108:   });
1109: 
1110:   return invokesHooks || createsJsx;
1111: }
