1157: /*
1158:  * Gets the static name of a function AST node. For function declarations it is
1159:  * easy. For anonymous function expressions it is much harder. If you search for
1160:  * `IsAnonymousFunctionDefinition()` in the ECMAScript spec you'll find places
1161:  * where JS gives anonymous function expressions names. We roughly detect the
1162:  * same AST nodes with some exceptions to better fit our use case.
1163:  */
1164: 
1165: function getFunctionName(
1166:   path: NodePath<
1167:     t.FunctionDeclaration | t.ArrowFunctionExpression | t.FunctionExpression
1168:   >,
1169: ): NodePath<t.Expression> | null {
1170:   if (path.isFunctionDeclaration()) {
1171:     const id = path.get('id');
1172:     if (id.isIdentifier()) {
1173:       return id;
1174:     }
1175:     return null;
1176:   }
1177:   let id: NodePath<t.LVal | t.Expression | t.PrivateName> | null = null;
1178:   const parent = path.parentPath;
1179:   if (parent.isVariableDeclarator() && parent.get('init').node === path.node) {
1180:     // const useHook = () => {};
1181:     id = parent.get('id');
1182:   } else if (
1183:     parent.isAssignmentExpression() &&
1184:     parent.get('right').node === path.node &&
1185:     parent.get('operator') === '='
1186:   ) {
1187:     // useHook = () => {};
1188:     id = parent.get('left');
1189:   } else if (
1190:     parent.isProperty() &&
1191:     parent.get('value').node === path.node &&
1192:     !parent.get('computed') &&
1193:     parent.get('key').isLVal()
1194:   ) {
1195:     /*
1196:      * {useHook: () => {}}
1197:      * {useHook() {}}
1198:      */
1199:     id = parent.get('key');
1200:   } else if (
1201:     parent.isAssignmentPattern() &&
1202:     parent.get('right').node === path.node &&
1203:     !parent.get('computed')
1204:   ) {
1205:     /*
1206:      * const {useHook = () => {}} = {};
1207:      * ({useHook = () => {}} = {});
1208:      *
1209:      * Kinda clowny, but we'd said we'd follow spec convention for
1210:      * `IsAnonymousFunctionDefinition()` usage.
1211:      */
1212:     id = parent.get('left');
1213:   }
1214:   if (id !== null && (id.isIdentifier() || id.isMemberExpression())) {
1215:     return id;
1216:   } else {
1217:     return null;
1218:   }
1219: }
1220: 
1221: function getFunctionReferencedBeforeDeclarationAtTopLevel(
1222:   program: NodePath<t.Program>,
1223:   fns: Array<CompileResult>,
1224: ): Set<CompileResult> {
1225:   const fnNames = new Map<string, {id: t.Identifier; fn: CompileResult}>(
1226:     fns
1227:       .map<[NodePath<t.Expression> | null, CompileResult]>(fn => [
1228:         getFunctionName(fn.originalFn),
1229:         fn,
1230:       ])
1231:       .filter(
1232:         (entry): entry is [NodePath<t.Identifier>, CompileResult] =>
1233:           !!entry[0] && entry[0].isIdentifier(),
1234:       )
1235:       .map(entry => [entry[0].node.name, {id: entry[0].node, fn: entry[1]}]),
1236:   );
1237:   const referencedBeforeDeclaration = new Set<CompileResult>();
1238: 
1239:   program.traverse({
1240:     TypeAnnotation(path) {
1241:       path.skip();
1242:     },
1243:     TSTypeAnnotation(path) {
1244:       path.skip();
1245:     },
1246:     TypeAlias(path) {
1247:       path.skip();
1248:     },
1249:     TSTypeAliasDeclaration(path) {
1250:       path.skip();
1251:     },
1252:     Identifier(id) {
1253:       const fn = fnNames.get(id.node.name);
1254:       // We're not tracking this identifier.
1255:       if (!fn) {
1256:         return;
1257:       }
1258: 
1259:       /*
1260:        * We've reached the declaration, hoisting is no longer possible, stop
1261:        * checking for this component name.
1262:        */
1263:       if (id.node === fn.id) {
1264:         fnNames.delete(id.node.name);
1265:         return;
1266:       }
1267: 
1268:       const scope = id.scope.getFunctionParent();
1269:       /*
1270:        * A null scope means there's no function scope, which means we're at the
1271:        * top level scope.
1272:        */
1273:       if (scope === null && id.isReferencedIdentifier()) {
1274:         referencedBeforeDeclaration.add(fn.fn);
1275:       }
1276:     },
1277:   });
1278: 
1279:   return referencedBeforeDeclaration;
1280: }
