353: export type CompileProgramMetadata = {
354:   retryErrors: Array<{fn: BabelFn; error: CompilerError}>;
355: };
356: /**
357:  * Main entrypoint for React Compiler.
358:  *
359:  * @param program The Babel program node to compile
360:  * @param pass Compiler configuration and context
361:  * @returns Compilation results or null if compilation was skipped
362:  */
363: export function compileProgram(
364:   program: NodePath<t.Program>,
365:   pass: CompilerPass,
366: ): CompileProgramMetadata | null {
367:   /**
368:    * This is directly invoked by the react-compiler babel plugin, so exceptions
369:    * thrown by this function will fail the babel build.
370:    * - call `handleError` if your error is recoverable.
371:    *   Unless the error is a warning / info diagnostic, compilation of a function
372:    *   / entire file should also be skipped.
373:    * - throw an exception if the error is fatal / not recoverable.
374:    *   Examples of this are invalid compiler configs or failure to codegen outlined
375:    *   functions *after* already emitting optimized components / hooks that invoke
376:    *   the outlined functions.
377:    */
378:   if (shouldSkipCompilation(program, pass)) {
379:     return null;
380:   }
381:   const restrictedImportsErr = validateRestrictedImports(
382:     program,
383:     pass.opts.environment,
384:   );
385:   if (restrictedImportsErr) {
386:     handleError(restrictedImportsErr, pass, null);
387:     return null;
388:   }
389:   /*
390:    * Record lint errors and critical errors as depending on Forget's config,
391:    * we may still need to run Forget's analysis on every function (even if we
392:    * have already encountered errors) for reporting.
393:    */
394:   const suppressions = findProgramSuppressions(
395:     pass.comments,
396:     /*
397:      * If the compiler is validating hooks rules and exhaustive memo dependencies, we don't need to check
398:      * for React ESLint suppressions
399:      */
400:     pass.opts.environment.validateExhaustiveMemoizationDependencies &&
401:       pass.opts.environment.validateHooksUsage
402:       ? null
403:       : (pass.opts.eslintSuppressionRules ?? DEFAULT_ESLINT_SUPPRESSIONS),
404:     // Always bail on Flow suppressions
405:     pass.opts.flowSuppressions,
406:   );
407: 
408:   const programContext = new ProgramContext({
409:     program: program,
410:     opts: pass.opts,
411:     filename: pass.filename,
412:     code: pass.code,
413:     suppressions,
414:     hasModuleScopeOptOut:
415:       findDirectiveDisablingMemoization(program.node.directives, pass.opts) !=
416:       null,
417:   });
418: 
419:   const queue: Array<CompileSource> = findFunctionsToCompile(
420:     program,
421:     pass,
422:     programContext,
423:   );
424:   const compiledFns: Array<CompileResult> = [];
425: 
426:   // outputMode takes precedence if specified
427:   const outputMode: CompilerOutputMode =
428:     pass.opts.outputMode ?? (pass.opts.noEmit ? 'lint' : 'client');
429:   while (queue.length !== 0) {
430:     const current = queue.shift()!;
431:     const compiled = processFn(
432:       current.fn,
433:       current.fnType,
434:       programContext,
435:       outputMode,
436:     );
437: 
438:     if (compiled != null) {
439:       for (const outlined of compiled.outlined) {
440:         CompilerError.invariant(outlined.fn.outlined.length === 0, {
441:           reason: 'Unexpected nested outlined functions',
442:           loc: outlined.fn.loc,
443:         });
444:         const fn = insertNewOutlinedFunctionNode(
445:           program,
446:           current.fn,
447:           outlined.fn,
448:         );
449:         fn.skip();
450:         programContext.alreadyCompiled.add(fn.node);
451:         if (outlined.type !== null) {
452:           queue.push({
453:             kind: 'outlined',
454:             fn,
455:             fnType: outlined.type,
456:           });
457:         }
458:       }
459:       compiledFns.push({
460:         kind: current.kind,
461:         originalFn: current.fn,
462:         compiledFn: compiled,
463:       });
464:     }
465:   }
466: 
467:   // Avoid modifying the program if we find a program level opt-out
468:   if (programContext.hasModuleScopeOptOut) {
469:     if (compiledFns.length > 0) {
470:       const error = new CompilerError();
471:       error.pushErrorDetail(
472:         new CompilerErrorDetail({
473:           reason:
474:             'Unexpected compiled functions when module scope opt-out is present',
475:           category: ErrorCategory.Invariant,
476:           loc: null,
477:         }),
478:       );
479:       handleError(error, programContext, null);
480:     }
481:     return null;
482:   }
483: 
484:   // Insert React Compiler generated functions into the Babel AST
485:   applyCompiledFunctions(program, compiledFns, pass, programContext);
486: 
487:   return {
488:     retryErrors: programContext.retryErrors,
489:   };
490: }
