492: type CompileSource = {
493:   kind: 'original' | 'outlined';
494:   fn: BabelFn;
495:   fnType: ReactFunctionType;
496: };
497: /**
498:  * Find all React components and hooks that need to be compiled
499:  *
500:  * @returns An array of React functions from @param program to transform
501:  */
502: function findFunctionsToCompile(
503:   program: NodePath<t.Program>,
504:   pass: CompilerPass,
505:   programContext: ProgramContext,
506: ): Array<CompileSource> {
507:   const queue: Array<CompileSource> = [];
508:   const traverseFunction = (fn: BabelFn, pass: CompilerPass): void => {
509:     // In 'all' mode, compile only top level functions
510:     if (
511:       pass.opts.compilationMode === 'all' &&
512:       fn.scope.getProgramParent() !== fn.scope.parent
513:     ) {
514:       return;
515:     }
516: 
517:     const fnType = getReactFunctionType(fn, pass);
518: 
519:     if (fnType === null || programContext.alreadyCompiled.has(fn.node)) {
520:       return;
521:     }
522: 
523:     /*
524:      * We may be generating a new FunctionDeclaration node, so we must skip over it or this
525:      * traversal will loop infinitely.
526:      * Ensure we avoid visiting the original function again.
527:      */
528:     programContext.alreadyCompiled.add(fn.node);
529:     fn.skip();
530: 
531:     queue.push({kind: 'original', fn, fnType});
532:   };
533: 
534:   // Main traversal to compile with Forget
535:   program.traverse(
536:     {
537:       ClassDeclaration(node: NodePath<t.ClassDeclaration>) {
538:         /*
539:          * Don't visit functions defined inside classes, because they
540:          * can reference `this` which is unsafe for compilation
541:          */
542:         node.skip();
543:       },
544: 
545:       ClassExpression(node: NodePath<t.ClassExpression>) {
546:         /*
547:          * Don't visit functions defined inside classes, because they
548:          * can reference `this` which is unsafe for compilation
549:          */
550:         node.skip();
551:       },
552: 
553:       FunctionDeclaration: traverseFunction,
554: 
555:       FunctionExpression: traverseFunction,
556: 
557:       ArrowFunctionExpression: traverseFunction,
558:     },
559:     {
560:       ...pass,
561:       opts: {...pass.opts, ...pass.opts},
562:       filename: pass.filename ?? null,
563:     },
564:   );
565:   return queue;
566: }
567: 
568: /**
569:  * Try to compile a source function, taking into account all local suppressions,
570:  * opt-ins, and opt-outs.
571:  *
572:  * Errors encountered during compilation are either logged (if recoverable) or
573:  * thrown (if non-recoverable).
574:  *
575:  * @returns the compiled function or null if the function was skipped (due to
576:  * config settings and/or outputs)
577:  */
578: function processFn(
579:   fn: BabelFn,
580:   fnType: ReactFunctionType,
581:   programContext: ProgramContext,
582:   outputMode: CompilerOutputMode,
583: ): null | CodegenFunction {
584:   let directives: {
585:     optIn: t.Directive | null;
586:     optOut: t.Directive | null;
587:   };
588:   if (fn.node.body.type !== 'BlockStatement') {
589:     directives = {
590:       optIn: null,
591:       optOut: null,
592:     };
593:   } else {
594:     const optIn = tryFindDirectiveEnablingMemoization(
595:       fn.node.body.directives,
596:       programContext.opts,
597:     );
598:     if (optIn.isErr()) {
599:       /**
600:        * If parsing opt-in directive fails, it's most likely that React Compiler
601:        * was not tested or rolled out on this function. In that case, we handle
602:        * the error and fall back to the safest option which is to not optimize
603:        * the function.
604:        */
605:       handleError(optIn.unwrapErr(), programContext, fn.node.loc ?? null);
606:       return null;
607:     }
608:     directives = {
609:       optIn: optIn.unwrapOr(null),
610:       optOut: findDirectiveDisablingMemoization(
611:         fn.node.body.directives,
612:         programContext.opts,
613:       ),
614:     };
615:   }
616: 
617:   let compiledFn: CodegenFunction;
618:   const compileResult = tryCompileFunction(
619:     fn,
620:     fnType,
621:     programContext,
622:     outputMode,
623:   );
624:   if (compileResult.kind === 'error') {
625:     if (directives.optOut != null) {
626:       logError(compileResult.error, programContext, fn.node.loc ?? null);
627:     } else {
628:       handleError(compileResult.error, programContext, fn.node.loc ?? null);
629:     }
630:     return null;
631:   } else {
632:     compiledFn = compileResult.compiledFn;
633:   }
634: 
635:   /**
636:    * If 'use no forget/memo' is present and we still ran the code through the
637:    * compiler for validation, log a skip event and don't mutate the babel AST.
638:    * This allows us to flag if there is an unused 'use no forget/memo'
639:    * directive.
640:    */
641:   if (
642:     programContext.opts.ignoreUseNoForget === false &&
643:     directives.optOut != null
644:   ) {
645:     programContext.logEvent({
646:       kind: 'CompileSkip',
647:       fnLoc: fn.node.body.loc ?? null,
648:       reason: `Skipped due to '${directives.optOut.value}' directive.`,
649:       loc: directives.optOut.loc ?? null,
650:     });
651:     return null;
652:   }
