1221: function getFunctionReferencedBeforeDeclarationAtTopLevel(
1222:   program: NodePath<t.Program>,
1223:   fns: Array<CompileResult>,
1224: ): Set<CompileResult> {
1225:   const fnNames = new Map<string, {id: t.Identifier; fn: CompileResult}>(
1226:     fns
1227:       .map<[NodePath<t.Expression> | null, CompileResult]>(fn => [
1228:         getFunctionName(fn.originalFn),
1229:         fn,
1230:       ])
1231:       .filter(
1232:         (entry): entry is [NodePath<t.Identifier>, CompileResult] =>
1233:           !!entry[0] && entry[0].isIdentifier(),
1234:       )
1235:       .map(entry => [entry[0].node.name, {id: entry[0].node, fn: entry[1]}]),
1236:   );
1237:   const referencedBeforeDeclaration = new Set<CompileResult>();
1238: 
1239:   program.traverse({
1240:     TypeAnnotation(path) {
1241:       path.skip();
1242:     },
1243:     TSTypeAnnotation(path) {
1244:       path.skip();
1245:     },
1246:     TypeAlias(path) {
1247:       path.skip();
1248:     },
1249:     TSTypeAliasDeclaration(path) {
1250:       path.skip();
1251:     },
1252:     Identifier(id) {
1253:       const fn = fnNames.get(id.node.name);
1254:       // We're not tracking this identifier.
1255:       if (!fn) {
1256:         return;
1257:       }
1258: 
1259:       /*
1260:        * We've reached the declaration, hoisting is no longer possible, stop
1261:        * checking for this component name.
1262:        */
1263:       if (id.node === fn.id) {
1264:         fnNames.delete(id.node.name);
1265:         return;
1266:       }
1267: 
1268:       const scope = id.scope.getFunctionParent();
1269:       /*
1270:        * A null scope means there's no function scope, which means we're at the
1271:        * top level scope.
1272:        */
1273:       if (scope === null && id.isReferencedIdentifier()) {
1274:         referencedBeforeDeclaration.add(fn.fn);
1275:       }
1276:     },
1277:   });
1278: 
1279:   return referencedBeforeDeclaration;
1280: }
