8: import {NodePath} from '@babel/core';
9: import * as t from '@babel/types';
10: import {Scope as BabelScope} from '@babel/traverse';
11: 
12: import {CompilerError, ErrorCategory} from '../CompilerError';
13: import {
14:   EnvironmentConfig,
15:   GeneratedSource,
16:   NonLocalImportSpecifier,
17: } from '../HIR';
18: import {getOrInsertWith} from '../Utils/utils';
19: import {ExternalFunction, isHookName} from '../HIR/Environment';
20: import {Err, Ok, Result} from '../Utils/Result';
21: import {LoggerEvent, ParsedPluginOptions} from './Options';
22: import {BabelFn, getReactCompilerRuntimeModule} from './Program';
23: import {SuppressionRange} from './Suppression';
24: 
25: export function validateRestrictedImports(
26:   path: NodePath<t.Program>,
27:   {validateBlocklistedImports}: EnvironmentConfig,
28: ): CompilerError | null {
29:   if (
30:     validateBlocklistedImports == null ||
31:     validateBlocklistedImports.length === 0
32:   ) {
33:     return null;
34:   }
35:   const error = new CompilerError();
36:   const restrictedImports = new Set(validateBlocklistedImports);
37:   path.traverse({
38:     ImportDeclaration(importDeclPath) {
39:       if (restrictedImports.has(importDeclPath.node.source.value)) {
40:         error.push({
41:           category: ErrorCategory.Todo,
42:           reason: 'Bailing out due to blocklisted import',
43:           description: `Import from module ${importDeclPath.node.source.value}`,
44:           loc: importDeclPath.node.loc ?? null,
45:         });
46:       }
47:     },
48:   });
49:   if (error.hasAnyErrors()) {
50:     return error;
51:   } else {
52:     return null;
53:   }
54: }
55: 
56: type ProgramContextOptions = {
57:   program: NodePath<t.Program>;
58:   suppressions: Array<SuppressionRange>;
59:   opts: ParsedPluginOptions;
60:   filename: string | null;
61:   code: string | null;
62:   hasModuleScopeOptOut: boolean;
63: };
64: export class ProgramContext {
65:   /**
66:    * Program and environment context
67:    */
68:   scope: BabelScope;
69:   opts: ParsedPluginOptions;
70:   filename: string | null;
71:   code: string | null;
72:   reactRuntimeModule: string;
73:   suppressions: Array<SuppressionRange>;
74:   hasModuleScopeOptOut: boolean;
75: 
76:   /*
77:    * This is a hack to work around what seems to be a Babel bug. Babel doesn't
78:    * consistently respect the `skip()` function to avoid revisiting a node within
79:    * a pass, so we use this set to track nodes that we have compiled.
80:    */
81:   alreadyCompiled: WeakSet<object> | Set<object> = new (WeakSet ?? Set)();
82:   // known generated or referenced identifiers in the program
83:   knownReferencedNames: Set<string> = new Set();
84:   // generated imports
85:   imports: Map<string, Map<string, NonLocalImportSpecifier>> = new Map();
86: 
87:   /**
88:    * Metadata from compilation
89:    */
90:   retryErrors: Array<{fn: BabelFn; error: CompilerError}> = [];
91: 
92:   constructor({
93:     program,
94:     suppressions,
95:     opts,
96:     filename,
97:     code,
98:     hasModuleScopeOptOut,
99:   }: ProgramContextOptions) {
100:     this.scope = program.scope;
101:     this.opts = opts;
102:     this.filename = filename;
103:     this.code = code;
104:     this.reactRuntimeModule = getReactCompilerRuntimeModule(opts.target);
105:     this.suppressions = suppressions;
106:     this.hasModuleScopeOptOut = hasModuleScopeOptOut;
107:   }
108: 
109:   isHookName(name: string): boolean {
110:     return isHookName(name);
111:   }
112: 
113:   hasReference(name: string): boolean {
114:     return (
115:       this.knownReferencedNames.has(name) ||
116:       this.scope.hasBinding(name) ||
117:       this.scope.hasGlobal(name) ||
118:       this.scope.hasReference(name)
119:     );
120:   }
121: 
122:   newUid(name: string): string {
123:     /**
124:      * Don't call babel's generateUid for known hook imports, as
125:      * InferTypes might eventually type `HookKind` based on callee naming
126:      * convention and `_useFoo` is not named as a hook.
127:      *
128:      * Local uid generation is susceptible to check-before-use bugs since we're
129:      * checking for naming conflicts / references long before we actually insert
130:      * the import. (see similar logic in HIRBuilder:resolveBinding)
131:      */
132:     let uid;
133:     if (this.isHookName(name)) {
134:       uid = name;
135:       let i = 0;
136:       while (this.hasReference(uid)) {
137:         this.knownReferencedNames.add(uid);
138:         uid = `${name}_${i++}`;
139:       }
140:     } else if (!this.hasReference(name)) {
141:       uid = name;
142:     } else {
143:       uid = this.scope.generateUid(name);
144:     }
145:     this.knownReferencedNames.add(uid);
146:     return uid;
147:   }
148: 
149:   addMemoCacheImport(): NonLocalImportSpecifier {
150:     return this.addImportSpecifier(
151:       {
152:         source: this.reactRuntimeModule,
153:         importSpecifierName: 'c',
154:       },
155:       '_c',
156:     );
157:   }
158: 
159:   /**
160:    *
161:    * @param externalFunction
162:    * @param nameHint if defined, will be used as the name of the import specifier
163:    * @returns
164:    */
165:   addImportSpecifier(
166:     {source: module, importSpecifierName: specifier}: ExternalFunction,
167:     nameHint?: string,
168:   ): NonLocalImportSpecifier {
169:     const maybeBinding = this.imports.get(module)?.get(specifier);
170:     if (maybeBinding != null) {
171:       return {...maybeBinding};
172:     }
173: 
174:     const binding: NonLocalImportSpecifier = {
175:       kind: 'ImportSpecifier',
176:       name: this.newUid(nameHint ?? specifier),
177:       module,
178:       imported: specifier,
179:     };
180:     getOrInsertWith(this.imports, module, () => new Map()).set(specifier, {
181:       ...binding,
182:     });
183:     return binding;
184:   }
185: 
186:   addNewReference(name: string): void {
187:     this.knownReferencedNames.add(name);
188:   }
189: 
190:   assertGlobalBinding(
191:     name: string,
192:     localScope?: BabelScope,
193:   ): Result<void, CompilerError> {
194:     const scope = localScope ?? this.scope;
195:     if (!scope.hasReference(name) && !scope.hasBinding(name)) {
196:       return Ok(undefined);
197:     }
198:     const error = new CompilerError();
199:     error.push({
200:       category: ErrorCategory.Todo,
201:       reason: 'Encountered conflicting global in generated program',
202:       description: `Conflict from local binding ${name}`,
203:       loc: scope.getBinding(name)?.path.node.loc ?? null,
204:       suggestions: null,
205:     });
206:     return Err(error);
207:   }
208: 
209:   logEvent(event: LoggerEvent): void {
210:     if (this.opts.logger != null) {
211:       this.opts.logger.logEvent(this.filename, event);
212:     }
213:   }
214: }
215: 
216: function getExistingImports(
217:   program: NodePath<t.Program>,
218: ): Map<string, NodePath<t.ImportDeclaration>> {
219:   const existingImports = new Map<string, NodePath<t.ImportDeclaration>>();
220:   program.traverse({
221:     ImportDeclaration(path) {
222:       if (isNonNamespacedImport(path)) {
223:         existingImports.set(path.node.source.value, path);
224:       }
225:     },
226:   });
227:   return existingImports;
228: }
229: 
230: export function addImportsToProgram(
231:   path: NodePath<t.Program>,
232:   programContext: ProgramContext,
233: ): void {
234:   const existingImports = getExistingImports(path);
235:   const stmts: Array<t.ImportDeclaration | t.VariableDeclaration> = [];
236:   const sortedModules = [...programContext.imports.entries()].sort(([a], [b]) =>
237:     a.localeCompare(b),
238:   );
239:   for (const [moduleName, importsMap] of sortedModules) {
240:     for (const [specifierName, loweredImport] of importsMap) {
241:       /**
242:        * Assert that the import identifier hasn't already be declared in the program.
243:        * Note: we use getBinding here since `Scope.hasBinding` pessimistically returns true
244:        * for all allocated uids (from `Scope.getUid`)
245:        */
246:       CompilerError.invariant(
247:         path.scope.getBinding(loweredImport.name) == null,
248:         {
249:           reason:
250:             'Encountered conflicting import specifiers in generated program',
251:           description: `Conflict from import ${loweredImport.module}:(${loweredImport.imported} as ${loweredImport.name})`,
252:           loc: GeneratedSource,
253:         },
254:       );
255:       CompilerError.invariant(
256:         loweredImport.module === moduleName &&
257:           loweredImport.imported === specifierName,
258:         {
259:           reason:
260:             'Found inconsistent import specifier. This is an internal bug.',
261:           description: `Expected import ${moduleName}:${specifierName} but found ${loweredImport.module}:${loweredImport.imported}`,
262:           loc: GeneratedSource,
263:         },
264:       );
265:     }
266:     const sortedImport: Array<NonLocalImportSpecifier> = [
267:       ...importsMap.values(),
268:     ].sort(({imported: a}, {imported: b}) => a.localeCompare(b));
269:     const importSpecifiers = sortedImport.map(specifier => {
270:       return t.importSpecifier(
271:         t.identifier(specifier.name),
272:         t.identifier(specifier.imported),
273:       );
274:     });
275: 
276:     /**
277:      * If an existing import of this module exists (ie `import { ... } from
278:      * '<moduleName>'`), inject new imported specifiers into the list of
279:      * destructured variables.
280:      */
281:     const maybeExistingImports = existingImports.get(moduleName);
282:     if (maybeExistingImports != null) {
283:       maybeExistingImports.pushContainer('specifiers', importSpecifiers);
284:     } else {
285:       if (path.node.sourceType === 'module') {
286:         stmts.push(
287:           t.importDeclaration(importSpecifiers, t.stringLiteral(moduleName)),
288:         );
289:       } else {
290:         stmts.push(
291:           t.variableDeclaration('const', [
292:             t.variableDeclarator(
293:               t.objectPattern(
294:                 sortedImport.map(specifier => {
295:                   return t.objectProperty(
296:                     t.identifier(specifier.imported),
297:                     t.identifier(specifier.name),
298:                   );
299:                 }),
300:               ),
301:               t.callExpression(t.identifier('require'), [
302:                 t.stringLiteral(moduleName),
303:               ]),
304:             ),
305:           ]),
306:         );
307:       }
308:     }
309:   }
310:   path.unshiftContainer('body', stmts);
311: }
312: 
313: /*
314:  * Matches `import { ... } from <moduleName>;`
315:  * but not `import * as React from <moduleName>;`
316:  *         `import type { Foo } from <moduleName>;`
317:  */
318: function isNonNamespacedImport(
319:   importDeclPath: NodePath<t.ImportDeclaration>,
320: ): boolean {
321:   return (
322:     importDeclPath
323:       .get('specifiers')
324:       .every(specifier => specifier.isImportSpecifier()) &&
325:     importDeclPath.node.importKind !== 'type' &&
326:     importDeclPath.node.importKind !== 'typeof'
327:   );
328: }
329: "}

