8: import {NodePath} from '@babel/core';
9: import * as t from '@babel/types';
10: 
11: import {CompilerError, EnvironmentConfig, Logger} from '..';
12: import {getOrInsertWith} from '../Utils/utils';
13: import {GeneratedSource} from '../HIR';
14: import {DEFAULT_EXPORT} from '../HIR/Environment';
15: import {CompileProgramMetadata} from './Program';
16: export default function validateNoUntransformedReferences(
17:   path: NodePath<t.Program>,
18:   filename: string | null,
19:   logger: Logger | null,
20:   env: EnvironmentConfig,
21:   compileResult: CompileProgramMetadata | null,
22: ): void {
23:   const moduleLoadChecks = new Map<
24:     string,
25:     Map<string, CheckInvalidReferenceFn>
26:   >();
27:   if (moduleLoadChecks.size > 0) {
28:     transformProgram(path, moduleLoadChecks, filename, logger, compileResult);
29:   }
30: }
31: 
32: type TraversalState = {
33:   shouldInvalidateScopes: boolean;
34:   program: NodePath<t.Program>;
35:   logger: Logger | null;
36:   filename: string | null;
37:   transformErrors: Array<{fn: NodePath<t.Node>; error: CompilerError}>;
38: };
39: type CheckInvalidReferenceFn = (
40:   paths: Array<NodePath<t.Node>>,
41:   context: TraversalState,
42: ) => void;
43: 
44: function validateImportSpecifier(
45:   specifier: NodePath<t.ImportSpecifier>,
46:   importSpecifierChecks: Map<string, CheckInvalidReferenceFn>,
47:   state: TraversalState,
48: ): void {
49:   const imported = specifier.get('imported');
50:   const specifierName: string =
51:     imported.node.type === 'Identifier'
52:       ? imported.node.name
53:       : imported.node.value;
54:   const checkFn = importSpecifierChecks.get(specifierName);
55:   if (checkFn == null) {
56:     return;
57:   }
58:   if (state.shouldInvalidateScopes) {
59:     state.shouldInvalidateScopes = false;
60:     state.program.scope.crawl();
61:   }
62: 
63:   const local = specifier.get('local');
64:   const binding = local.scope.getBinding(local.node.name);
65:   CompilerError.invariant(binding != null, {
66:     reason: 'Expected binding to be found for import specifier',
67:     loc: local.node.loc ?? GeneratedSource,
68:   });
69:   checkFn(binding.referencePaths, state);
70: }
71: 
72: function validateNamespacedImport(
73:   specifier: NodePath<t.ImportNamespaceSpecifier | t.ImportDefaultSpecifier>,
74:   importSpecifierChecks: Map<string, CheckInvalidReferenceFn>,
75:   state: TraversalState,
76: ): void {
77:   if (state.shouldInvalidateScopes) {
78:     state.shouldInvalidateScopes = false;
79:     state.program.scope.crawl();
80:   }
81:   const local = specifier.get('local');
82:   const binding = local.scope.getBinding(local.node.name);
83:   const defaultCheckFn = importSpecifierChecks.get(DEFAULT_EXPORT);
84: 
85:   CompilerError.invariant(binding != null, {
86:     reason: 'Expected binding to be found for import specifier',
87:     loc: local.node.loc ?? GeneratedSource,
88:   });
89:   const filteredReferences = new Map<
90:     CheckInvalidReferenceFn,
91:     Array<NodePath<t.Node>>
92:   >();
93:   for (const reference of binding.referencePaths) {
94:     if (defaultCheckFn != null) {
95:       getOrInsertWith(filteredReferences, defaultCheckFn, () => []).push(
96:         reference,
97:       );
98:     }
99:     const parent = reference.parentPath;
100:     if (
101:       parent != null &&
102:       parent.isMemberExpression() &&
103:       parent.get('object') === reference
104:     ) {
105:       if (parent.node.computed || parent.node.property.type !== 'Identifier') {
106:         continue;
107:       }
108:       const checkFn = importSpecifierChecks.get(parent.node.property.name);
109:       if (checkFn != null) {
110:         getOrInsertWith(filteredReferences, checkFn, () => []).push(parent);
111:       }
112:     }
113:   }
114: 
115:   for (const [checkFn, references] of filteredReferences) {
116:     checkFn(references, state);
117:   }
118: }
119: function transformProgram(
120:   path: NodePath<t.Program>,
121: 
122:   moduleLoadChecks: Map<string, Map<string, CheckInvalidReferenceFn>>,
123:   filename: string | null,
124:   logger: Logger | null,
125:   compileResult: CompileProgramMetadata | null,
126: ): void {
127:   const traversalState: TraversalState = {
128:     shouldInvalidateScopes: true,
129:     program: path,
130:     filename,
131:     logger,
132:     transformErrors: compileResult?.retryErrors ?? [],
133:   };
134:   path.traverse({
135:     ImportDeclaration(path: NodePath<t.ImportDeclaration>) {
136:       const importSpecifierChecks = moduleLoadChecks.get(
137:         path.node.source.value,
138:       );
139:       if (importSpecifierChecks == null) {
140:         return;
141:       }
142:       const specifiers = path.get('specifiers');
143:       for (const specifier of specifiers) {
144:         if (specifier.isImportSpecifier()) {
145:           validateImportSpecifier(
146:             specifier,
147:             importSpecifierChecks,
148:             traversalState,
149:           );
150:         } else {
151:           validateNamespacedImport(
152:             specifier as NodePath<
153:               t.ImportNamespaceSpecifier | t.ImportDefaultSpecifier
154:             >,
155:             importSpecifierChecks,
156:             traversalState,
157:           );
158:         }
159:       }
160:     },
161:   });
162: }
