17: const ENABLE_REACT_COMPILER_TIMINGS =
18:   process.env['ENABLE_REACT_COMPILER_TIMINGS'] === '1';
19: 
20: /*
21:  * The React Forget Babel Plugin
22:  * @param {*} _babel
23:  * @returns
24:  */
25: export default function BabelPluginReactCompiler(
26:   _babel: typeof BabelCore,
27: ): BabelCore.PluginObj {
28:   return {
29:     name: 'react-forget',
30:     visitor: {
31:       /*
32:        * Note: Babel does some "smart" merging of visitors across plugins, so even if A is inserted
33:        * prior to B, if A does not have a Program visitor and B does, B will run first. We always
34:        * want Forget to run true to source as possible.
35:        */
36:       Program: {
37:         enter(prog, pass): void {
38:           try {
39:             const filename = pass.filename ?? 'unknown';
40:             if (ENABLE_REACT_COMPILER_TIMINGS === true) {
41:               performance.mark(`${filename}:start`, {
42:                 detail: 'BabelPlugin:Program:start',
43:               });
44:             }
45:             let opts = parsePluginOptions(pass.opts);
46:             const isDev =
47:               (typeof __DEV__ !== 'undefined' && __DEV__ === true) ||
48:               process.env['NODE_ENV'] === 'development';
49:             if (
50:               opts.enableReanimatedCheck === true &&
51:               pipelineUsesReanimatedPlugin(pass.file.opts.plugins)
52:             ) {
53:               opts = injectReanimatedFlag(opts);
54:             }
55:             if (
56:               opts.environment.enableResetCacheOnSourceFileChanges !== false &&
57:               isDev
58:             ) {
59:               opts = {
60:                 ...opts,
61:                 environment: {
62:                   ...opts.environment,
63:                   enableResetCacheOnSourceFileChanges: true,
64:                 },
65:               };
66:             }
67:             const result = compileProgram(prog, {
68:               opts,
69:               filename: pass.filename ?? null,
70:               comments: pass.file.ast.comments ?? [],
71:               code: pass.file.code,
72:             });
73:             validateNoUntransformedReferences(
74:               prog,
75:               pass.filename ?? null,
76:               opts.logger,
77:               opts.environment,
78:               result,
79:             );
80:             if (ENABLE_REACT_COMPILER_TIMINGS === true) {
81:               performance.mark(`${filename}:end`, {
82:                 detail: 'BabelPlugin:Program:end',
83:               });
84:             }
85:           } catch (e) {
86:             if (e instanceof CompilerError) {
87:               throw e.withPrintedMessage(pass.file.code, {eslint: false});
88:             }
89:             throw e;
90:           }
91:         },
92:         exit(_, pass): void {
93:           if (ENABLE_REACT_COMPILER_TIMINGS === true) {
94:             const filename = pass.filename ?? 'unknown';
95:             const measurement = performance.measure(filename, {
96:               start: `${filename}:start`,
97:               end: `${filename}:end`,
98:               detail: 'BabelPlugin:Program',
99:             });
100:             if ('logger' in pass.opts && pass.opts.logger != null) {
101:               const logger: Logger = pass.opts.logger as Logger;
102:               logger.logEvent(filename, {
103:                 kind: 'Timing',
104:                 measurement,
105:               });
106:             }
107:           }
108:         },
109:       },
110:     },
111:   };
112: }
